def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = list(map(int, data[1:1 + n]))
    M = max(a) + 1
    spf = list(range(M))
    i = 2
    while i * i < M:
        if spf[i] == i:
            for j in range(i * i, M, i):
                if spf[j] == j:
                    spf[j] = i
        i += 1
    omega = [0] * M
    for v in range(2, M):
        omega[v] = omega[v // spf[v]] + 1
    x = 0
    for v in a:
        x ^= omega[v]
    print("Anna" if x != 0 else "Bruno")

