from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        by_b = [[] for _ in range(n + 1)]
        for i, (x, y) in enumerate(conflictingPairs):
            a, b = min(x, y), max(x, y)
            by_b[b].append((a, i))
        gain = [0] * m
        top1 = 0
        top1_idx = -1
        second = 0
        base = 0
        for r in range(1, n + 1):
            for a, i in by_b[r]:
                if a > top1:
                    second = top1
                    top1 = a
                    top1_idx = i
                elif a > second:
                    second = a
            base += r - top1
            if top1_idx >= 0:
                gain[top1_idx] += top1 - second
        return base + (max(gain) if m > 0 else 0)

