import itertools
def lis(p):
    n=len(p); d=[1]*n
    for i in range(n):
        for j in range(i):
            if p[j]<p[i]: d[i]=max(d[i],d[j]+1)
    return max(d) if n else 0
def lds(p): return lis([-x for x in p])
def brute(A,B):
    N=A*B-1; c=0
    for p in itertools.permutations(range(1,N+1)):
        if lis(p)!=A or lds(p)!=B: continue
        ok=False
        for k in range(0,N+1):
            q=list(p)+[k+0.5]
            if lis(q)==A and lds(q)==B: ok=True;break
        if ok: c+=1
    return c
