import sys, random, itertools
from functools import lru_cache
sys.setrecursionlimit(100000)
def solve(boxes, M):
    N=len(boxes)
    @lru_cache(None)
    def f(U, r):
        best=None
        for t in range(M):
            if t>0 and r[t]==r[t-1]: continue
            opts=[0]
            if r[t]>0:
                rr=list(r); rr[t]-=1
                opts.append(1+f(U, tuple(sorted(rr))))
            for j in range(N):
                if U>>j&1:
                    V,P=boxes[j]
                    rr=list(r); rr[t]+=V-1
                    opts.append(1-P+f(U&~(1<<j), tuple(sorted(rr))))
            val=max(opts)
            best=val if best is None else min(best,val)
        return best
    return f((1<<N)-1, tuple([0]*M))
