class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)

        def steps(c):
            cnt = 0
            while c != 1:
                c = bin(c).count('1')
                cnt += 1
            return cnt

        G = [c for c in range(1, L + 1) if steps(c) <= k - 1]

        C = [[0] * (L + 1) for _ in range(L + 1)]
        for i in range(L + 1):
            C[i][0] = 1
            for j in range(1, i + 1):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

        cnt = [0] * (L + 1)
        ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = L - i - 1
                for c in range(L + 1):
                    need = c - ones
                    if 0 <= need <= rem:
                        cnt[c] = (cnt[c] + C[rem][need]) % MOD
                ones += 1
        # cnt[c] counts x in [0, n-1] with popcount c; x=0 has popcount 0 and is excluded from G
        ans = 0
        for c in G:
            ans = (ans + cnt[c]) % MOD
        return ans

