import sys
def main():
    data=sys.stdin.read().split()
    n=int(data[0]); g=data[1:1+n]
    letters=set(ch for row in g for ch in row if ch!='-')
    inl={c:[[] for _ in range(n)] for c in letters}
    outm={c:[0]*n for c in letters}
    edge=[[False]*n for _ in range(n)]
    for u in range(n):
        for v in range(n):
            ch=g[u][v]
            if ch!='-':
                inl[ch][v].append(u)
                outm[ch][u]|=(1<<v)
                edge[u][v]=True
    full=(1<<n)-1
    unvis=[full]*n
    D=[[-1]*n for _ in range(n)]
    LIM=2*n*n+10
    buckets=[[] for _ in range(LIM+3)]
    for u in range(n):
        for v in range(n):
            if u==v:
                D[u][v]=0
                unvis[u]&=~(1<<v)
                buckets[0].append((u,v))
            elif edge[u][v]:
                D[u][v]=1
                unvis[u]&=~(1<<v)
                buckets[1].append((u,v))
    for d in range(LIM+1):
        bk=buckets[d]
        if not bk: continue
        nd=d+2
        for (up,vp) in bk:
            for c in letters:
                om=outm[c][vp]
                if not om: continue
                for u in inl[c][up]:
                    nv=om & unvis[u]
                    if nv:
                        unvis[u]^=nv
                        row=D[u]
                        while nv:
                            b=nv & -nv
                            v=b.bit_length()-1
                            row[v]=nd
                            buckets[nd].append((u,v))
                            nv^=b
        buckets[d]=None
    out=[]
    for u in range(n):
        out.append(' '.join(str(x) for x in D[u]))
    print('\n'.join(out))
main()

