import sys
from functools import lru_cache
from collections import Counter

def main():
    sys.setrecursionlimit(10000)
    data = sys.stdin.read().split()
    n = int(data[0])
    A = [int(x) for x in data[1:1 + n]]
    INF = 10**18
    D = 100

    @lru_cache(maxsize=None)
    def F(terms, nz, depth):
        if depth == 0:
            if nz:
                return INF
            return sum(c for b, t, c in terms if t == 1 and b % 2 == 0)
        best = INF
        for q in (0, 1):
            const = 0
            new = Counter()
            for b, t, c in terms:
                r = q + b
                if t == 1:
                    if r % 2 == 0:
                        const += c
                else:
                    if r % 2 == 0:
                        new[(r // 2, 0)] += c
                    else:
                        new[((r - 1) // 2, 1)] += c
            sub = F(tuple(sorted((b, t, c) for (b, t), c in new.items())), nz and q == 0, depth - 1)
            if sub < INF:
                best = min(best, const + sub)
        return best

    init = Counter()
    for a in A:
        init[(a, 0)] += 1
    m = F(tuple(sorted((b, t, c) for (b, t), c in init.items())), True, D)
    print(len(A) - m)

