class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid); m = len(grid[0])
        nv = {1: 2, 2: 0, 0: 2}
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        F0 = []
        for di, dj in dirs:
            f = [[0] * m for _ in range(n)]
            ri = range(n - 1, -1, -1) if di == 1 else range(n)
            cj = range(m - 1, -1, -1) if dj == 1 else range(m)
            for i in ri:
                for j in cj:
                    a, b = i + di, j + dj
                    if 0 <= a < n and 0 <= b < m and grid[a][b] == nv[grid[i][j]]:
                        f[i][j] = 1 + f[a][b]
            F0.append(f)
        best = 0
        for k, (di, dj) in enumerate(dirs):
            ck = (k + 1) % 4
            cdi, cdj = dirs[ck]
            f1 = [[0] * m for _ in range(n)]
            ri = range(n - 1, -1, -1) if di == 1 else range(n)
            cj = range(m - 1, -1, -1) if dj == 1 else range(m)
            f0t = F0[ck]
            for i in ri:
                for j in cj:
                    v = nv[grid[i][j]]
                    best_here = 0
                    a, b = i + di, j + dj
                    if 0 <= a < n and 0 <= b < m and grid[a][b] == v:
                        best_here = 1 + f1[a][b]
                    t, u = i + cdi, j + cdj
                    if 0 <= t < n and 0 <= u < m and grid[t][u] == v:
                        c = 1 + f0t[t][u]
                        if c > best_here:
                            best_here = c
                    f1[i][j] = best_here
                    if grid[i][j] == 1 and best_here + 1 > best:
                        best = best_here + 1
        if best == 0:
            for row in grid:
                if 1 in row:
                    return 1
        return best

