import math
from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        def g(o, e, q):
            # q=1: first element odd; q=0: first element even
            if o + e == 0:
                return 1
            if q == 1:
                ok = (o == e or o == e + 1)
            else:
                ok = (e == o or e == o + 1)
            if not ok:
                return 0
            return math.factorial(o) * math.factorial(e)

        def counts(rem):
            o = sum(1 for x in rem if x % 2 == 1)
            return o, len(rem) - o

        rem = list(range(1, n + 1))
        o, e = counts(rem)
        total = g(o, e, 1) + g(o, e, 0)
        if k > total:
            return []
        res = []
        last = None
        while rem:
            for idx, x in enumerate(rem):
                px = x % 2
                if last is not None and px == last:
                    continue
                rest = rem[:idx] + rem[idx + 1:]
                ro, re_ = counts(rest)
                cnt = g(ro, re_, 1 - px)
                if k <= cnt:
                    res.append(x)
                    rem = rest
                    last = px
                    break
                k -= cnt
            else:
                return []
        return res

