class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        p = [1 % k] * n
        for j in range(1, n):
            p[j] = p[j - 1] * 10 % k
        w = []
        for i in range(h):
            j = n - 1 - i
            w.append((p[j] + p[i]) % k if j != i else p[i])
        good = [None] * (h + 1)
        good[h] = [False] * k
        good[h][0] = True
        for i in range(h - 1, -1, -1):
            nxt = good[i + 1]
            cur = [False] * k
            for d in range(1 if i == 0 else 0, 10):
                t = w[i] * d % k
                for s in range(k):
                    if nxt[s]:
                        cur[(s + t) % k] = True
            good[i] = cur
        r = 0
        digits = []
        for i in range(h):
            for d in range(9, (0 if i else 1) - 1, -1):
                t = w[i] * d % k
                nr = (r - t) % k
                if good[i + 1][nr]:
                    digits.append(d)
                    r = nr
                    break
        s = ''.join(map(str, digits))
        return s + s[:n // 2][::-1]

