import sys
sys.setrecursionlimit(10000)
class Solution:
    def countNonDecreasingSubarrays(self, nums, k):
        n = len(nums)
        size = 4 * n
        sm = [0] * size
        lz = [-1] * size
        def apply(node, lo, hi, v):
            sm[node] = v * (hi - lo + 1)
            lz[node] = v
        def assign(node, lo, hi, l, r, v):
            if r < lo or hi < l:
                return
            if l <= lo and hi <= r:
                apply(node, lo, hi, v)
                return
            mid = (lo + hi) // 2
            if lz[node] != -1:
                apply(2 * node, lo, mid, lz[node])
                apply(2 * node + 1, mid + 1, hi, lz[node])
                lz[node] = -1
            assign(2 * node, lo, mid, l, r, v)
            assign(2 * node + 1, mid + 1, hi, l, r, v)
            sm[node] = sm[2 * node] + sm[2 * node + 1]
        def query(node, lo, hi, l, r):
            if r < lo or hi < l:
                return 0
            if l <= lo and hi <= r:
                return sm[node]
            mid = (lo + hi) // 2
            if lz[node] != -1:
                apply(2 * node, lo, mid, lz[node])
                apply(2 * node + 1, mid + 1, hi, lz[node])
                lz[node] = -1
            return query(2 * node, lo, mid, l, r) + query(2 * node + 1, mid + 1, hi, l, r)
        pre = [0] * (n + 1)
        for i in range(n):
            pre[i + 1] = pre[i] + nums[i]
        stack = []
        ans = 0
        r = n - 1
        for l in range(n - 1, -1, -1):
            v = nums[l]
            end = l
            while stack and stack[-1][1] <= v:
                s, bv, e = stack.pop()
                end = e
            stack.append((l, v, end))
            assign(1, 0, n - 1, l, end, v)
            def cost(r):
                return query(1, 0, n - 1, l, r) - (pre[r + 1] - pre[l])
            while cost(r) > k:
                r -= 1
            ans += r - l + 1
        return ans

