        n = len(nums)
        byLen = [[] for _ in range(n + 1)]
        for idx, (l, r) in enumerate(queries):
            byLen[r - l + 1].append((idx, l))
        ans = [0] * len(queries)
        F = list(nums)
        B = list(nums)
        for idx, l in byLen[1]:
            ans[idx] = B[l]
        for length in range(2, n + 1):
            m = n - length + 1
            F = [a ^ b for a, b in zip(F[:m], F[1:m + 1])]
            B = [max(f, b1, b2) for f, b1, b2 in zip(F, B[:m], B[1:m + 1])]
            for idx, l in byLen[length]:
                ans[idx] = B[l]
