class Solution:
    def makeStringGood(self, s: str) -> int:
        n = len(s)
        cnt = [0]*26
        for ch in s:
            cnt[ord(ch)-97] += 1
        INF = float('inf')
        best = n
        maxc = max(cnt)
        for f in range(1, min(n, maxc + 26) + 1):
            dp = {0: 0}
            for i in range(26):
                ndp = {}
                for j, c in dp.items():
                    a = cnt[i] + j
                    xmax = min(a, f) if i < 25 else 0
                    for x in range(xmax + 1):
                        k = a - x
                        tc = min(abs(k - f), k)
                        tot = c + x + tc
                        if tot < ndp.get(x, INF):
                            ndp[x] = tot
                dp = ndp
            if 0 in dp:
                best = min(best, dp[0])
        return best

