from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        def occ(pat, t):
            if not pat:
                return list(range(len(t) + 1))
            m = len(pat)
            pi = [0] * m
            k = 0
            for i in range(1, m):
                while k and pat[i] != pat[k]:
                    k = pi[k - 1]
                if pat[i] == pat[k]:
                    k += 1
                pi[i] = k
            res = []
            k = 0
            for i, ch in enumerate(t):
                while k and ch != pat[k]:
                    k = pi[k - 1]
                if ch == pat[k]:
                    k += 1
                if k == m:
                    res.append(i - m + 1)
                    k = pi[k - 1]
            return res

        a, b, c = p.split('*')
        A = occ(a, s)
        B = occ(b, s)
        C = occ(c, s)
        best = -1
        for i in A:
            j = bisect_left(B, i + len(a))
            if j == len(B):
                continue
            jb = B[j]
            k = bisect_left(C, jb + len(b))
            if k == len(C):
                continue
            length = C[k] + len(c) - i
            if best == -1 or length < best:
                best = length
        return best

