def main():
    data = sys.stdin.read().split()
    n, k = int(data[0]), int(data[1])
    A = [int(x) for x in data[2:2+n]]
    total = 0
    for a in A:
        total ^= a
    m = min(k, n - k)
    if m == 0:
        print(total); return
    if m == 1:
        if k == 1:
            print(max(A))
        else:
            print(max(total ^ a for a in A))
        return
    L = [np.array([0], dtype=np.int64)] + [np.array([], dtype=np.int64) for _ in range(m)]
    for a in A:
        for j in range(m, 0, -1):
            if L[j-1].size == 0:
                continue
            new = L[j-1] ^ np.int64(a)
            L[j] = np.unique(np.concatenate((L[j], new)))
    if k <= n - k:
        print(int(L[m].max()))
    else:
        print(int(np.bitwise_xor(np.int64(total), L[m]).max()))
