import sys
from collections import deque

def bfs(N, A, B):
    def step(mask, i):
        nm = 0
        for j in range(1, N + 1):
            if mask >> (j - 1) & 1:
                nj = j - 1 if i < j else (j + 1 if i > j else j)
                nm |= 1 << (nj - 1)
        return nm
    dist = {A: 0}
    dq = deque([A])
    while dq:
        m = dq.popleft()
        if m == B:
            return dist[m]
        for i in range(1, N + 1):
            nm = step(m, i)
            if nm not in dist:
                dist[nm] = dist[m] + 1
                dq.append(nm)
    return -1

def heur(N, P, S):
    k = len(P); m = len(S)
    if m > k:
        return -1
    g = [P[x + 1] - P[x] for x in range(k - 1)]
    bnd = []
