import sys, random

def main():
    data = sys.stdin.read().split()
    K = int(data[0]); S = data[1]; T = data[2]
    n, m = len(S), len(T)
    if abs(n - m) > K:
        print("No"); return
    M = (1 << 61) - 1
    B = random.randrange(10**6, 10**9)
    def build(s):
        h = [0] * (len(s) + 1)
        x = 0
        for idx, c in enumerate(s):
            x = (x * B + ord(c)) % M
            h[idx + 1] = x
        return h
    hs = build(S); ht = build(T)
    pw = [1] * (max(n, m) + 1)
    for i in range(1, len(pw)):
        pw[i] = pw[i - 1] * B % M

    def lcp(i, j):
        hi = min(n - i, m - j)
        lo = 0
        while lo < hi:
            mid = (lo + hi + 1) // 2
            a = (hs[i + mid] - hs[i] * pw[mid]) % M
            b = (ht[j + mid] - ht[j] * pw[mid]) % M
            if a == b:
                lo = mid
            else:
                hi = mid - 1
        return lo

    target = m - n
    prev = {}
    i0 = lcp(0, 0)
    prev[0] = i0
    if target == 0 and i0 >= n:
        print("Yes"); return
    for e in range(1, K + 1):
        cur = {}
        for k in range(-e, e + 1):
            best = -1
            if k in prev:
                best = max(best, prev[k] + 1)
            if (k - 1) in prev:
                best = max(best, prev[k - 1])
            if (k + 1) in prev:
                best = max(best, prev[k + 1] + 1)
            if best < 0:
                continue
            i = min(best, n, m - k)
            if i < 0 or i + k < 0:
                continue
            i += lcp(i, i + k)
            cur[k] = i
            if k == target and i >= n:
                print("Yes"); return
        prev = cur
    print("No")

main()

