from typing import List
class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)
        order = [0]
        for x in order:
            order.extend(children[x])
        sz = [1] * n
        for x in reversed(order):
            if parent[x] != -1:
                sz[parent[x]] += sz[x]
        start = [0] * n
        for x in order:
            cur = start[x]
            for c in children[x]:
                start[c] = cur
                cur += sz[c]
        T = [''] * n
        for x in range(n):
            T[start[x] + sz[x] - 1] = s[x]
        m = 2 * n + 1
        t = ['#'] * m
        for i in range(n):
            t[2 * i + 1] = T[i]
        P = [0] * m
        c = r = 0
        for i in range(m):
            if i < r:
                P[i] = min(r - i, P[2 * c - i])
            while i - P[i] - 1 >= 0 and i + P[i] + 1 < m and t[i - P[i] - 1] == t[i + P[i] + 1]:
                P[i] += 1
            if i + P[i] > r:
                c = i
                r = i + P[i]
        ans = []
        for x in range(n):
            l = start[x]
            rr = l + sz[x] - 1
            L = sz[x]
            ans.append(P[l + rr + 1] >= L)
        return ans

