from math import isqrt
from itertools import accumulate

def main():
    N = int(input())
    S = isqrt(N)
    n = max(S, 2)
    sv = bytearray([1]) * (n + 1)
    sv[0] = 0
    sv[1] = 0
    for i in range(2, isqrt(n) + 1):
        if sv[i]:
            sv[i*i::i] = bytearray(len(range(i*i, n + 1, i)))
    pi = list(accumulate(sv))
    primes = [i for i in range(n + 1) if sv[i]]
    total = 0
    # p^8 <= N
    for p in primes:
        if p ** 8 <= N:
            total += 1
        else:
            break
    # p^2 q^2 <= N with p < q  <=> p*q <= S
    for p in primes:
        if p * p >= S:
            break
        qmax = S // p
        if qmax > p:
            total += pi[qmax] - pi[p]
    print(total)

main()

