    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        for _ in range(t):
            new = [0] * 26
            new[0] = cnt[25]
            new[1] = (cnt[0] + cnt[25]) % MOD
            for i in range(2, 26):
                new[i] = cnt[i - 1]
