                return True
            if sorted(s) != sorted(t):
                return False
            diff = [i for i in range(W) if s[i] != t[i]]
            return len(diff) == 2

        count = 0
        for i in range(n):
            for j in range(i + 1, n):
                if almost(strs[i], strs[j]):
                    count += 1
        return count

