from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        ans = 0
        for i in range(n):
            target = nums[i]
            if target == 0:
                continue
            mask = (1 << (target + 1)) - 1
            reach = 1
            found = -1
            for k, (l, r, v) in enumerate(queries):
                if l <= i <= r:
                    reach = (reach | (reach << v)) & mask
                if (reach >> target) & 1:
                    found = k + 1
                    break
            if found < 0:
                return -1
            ans = max(ans, found)
        return ans

