import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        LIM = 10000
        sieve = [True] * LIM
        sieve[0] = sieve[1] = False
        for i in range(2, int(LIM ** 0.5) + 1):
            if sieve[i]:
                for j in range(i * i, LIM, i):
                    sieve[j] = False
        if sieve[n] or sieve[m]:
            return -1
        if n == m:
            return n
        k = len(str(n))
        p = 10 ** (k - 1)
        dist = {n: n}
        pq = [(n, n)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist.get(u, float('inf')):
                continue
            if u == m:
                return d
            digits = [(u // (10 ** i)) % 10 for i in range(k)]
            for i in range(k):
                pw = 10 ** i
                dig = digits[i]
                for delta in (1, -1):
                    nd = dig + delta
                    if nd < 0 or nd > 9:
                        continue
                    v = u + delta * pw
                    if v <= 0 or v >= LIM or sieve[v]:
                        continue
                    nc = d + v
                    if nc < dist.get(v, float('inf')):
                        dist[v] = nc
                        heapq.heappush(pq, (nc, v))
        return -1

