class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n, m = len(source), len(pattern)
        tset = set(targetIndices)
        NEG = float('-inf')
        dp = [NEG] * (m + 1)
        dp[0] = 0
        pos = {}
        for j, c in enumerate(pattern):
            pos.setdefault(c, []).append(j)
        for i in range(n):
            t = 1 if i in tset else 0
            new = [x + t if x != NEG else NEG for x in dp]
            for j in pos.get(source[i], ()):
                if dp[j] != NEG and dp[j] > new[j + 1]:
                    new[j + 1] = dp[j]
            dp = new
        return int(dp[m])

