class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        runs = []
        i = 0
        n = len(s)
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            runs.append((s[i], j - i))
            i = j
        ones = s.count('1')
        best = 0
        for k in range(1, len(runs) - 1):
            if runs[k][0] == '1':
                g = runs[k - 1][1] + runs[k + 1][1]
                if g > best:
                    best = g
        return ones + best

