class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        pts = set((p[0], p[1]) for p in points)
        xs = sorted(set(p[0] for p in points))
        ys = sorted(set(p[1] for p in points))
        best = -1
        for i in range(len(xs)):
            for j in range(i + 1, len(xs)):
                x1, x2 = xs[i], xs[j]
                for k in range(len(ys)):
                    for l in range(k + 1, len(ys)):
                        y1, y2 = ys[k], ys[l]
                        if (x1, y1) not in pts or (x1, y2) not in pts or \
                           (x2, y1) not in pts or (x2, y2) not in pts:
                            continue
                        corners = {(x1, y1), (x1, y2), (x2, y1), (x2, y2)}
                        ok = True
                        for (px, py) in pts:
                            if x1 <= px <= x2 and y1 <= py <= y2 and (px, py) not in corners:
                                ok = False
                                break
                        if ok:
                            area = (x2 - x1) * (y2 - y1)
                            if area > best:
                                best = area
        return best

